        sol_gaseif_syngas4_desc: "Base para metanol, amônia e hidrogênio verde via processos de purificação (PSA).",
        sol_gaseif_publico_kicker: "Para quem é",
        sol_gaseif_publico_title: "Indústria e gestão pública.",
        sol_gaseif_ind_tagline: "Autossuficiência &amp; ESG",
        sol_gaseif_ind_title: "Indústrias e parques fabris",
        sol_gaseif_ind_p1: "Para a indústria, resíduo é custo logístico e passivo ambiental. Transformamos sobras de processo, embalagens e biomassas em energia térmica ou elétrica para autoconsumo.",
        sol_gaseif_ind_p2: "Reduz a dependência da rede, zera o envio para aterros e gera créditos de carbono reais para o balanço de sustentabilidade.",
        sol_gaseif_mun_tagline: "PNRS &amp; logística",
        sol_gaseif_mun_title: "Gestão pública e consórcios",
        sol_gaseif_mun_p1: "O desafio municipal é o volume e a heterogeneidade do RSU. Instalamos módulos próximos aos centros de geração, eliminando transbordos e reduzindo drasticamente o custo de frete.",
        sol_gaseif_mun_p2: "Transforma o \"lixo comum\", após triagem, em fonte de receita por venda de energia e economia nas taxas de disposição final.",
