        inv_form_submit: "Enviar solicitação",
        inv_form_disclaimer1: "Ao enviar, você solicita análise individual. Não é uma oferta pública. Compartilhamos informações apenas sob confidencialidade.",
        inv_form_legal: "As informações aqui apresentadas não constituem oferta pública de valores mobiliários, não representam recomendação de investimento e estão sujeitas a riscos. Investimentos em projetos de infraestrutura envolvem riscos operacionais, regulatórios e de mercado. Os rendimentos projetados são estimativas baseadas em modelagem financeira e não garantem retorno futuro. Consulte um assessor financeiro qualificado antes de investir. <span class=\"legal-company-name\" style=\"white-space:nowrap\">4WaTT Bio Engenharia S/A</span><span class=\"legal-company-cnpj\" style=\"white-space:nowrap\"> — CNPJ 36.561.483/0001-40.</span>",
        inv_footer_contato: "CONTATO",
