        bm_cert1_auth: "ANP / Ministry of Mines and Energy",
        bm_cert1_text: "RenovaBio is the public policy for decarbonizing the transport and industry sectors. Each m³ of certified biomethane generates CBIOs (decarbonization credits traded on B3) that supplement producer revenue and make biomethane more competitive than fossil natural gas.",
        bm_cert2_title: "CBIO B3",
